)

// Run executes the internal agent loop: send prompt, process tool calls, repeat
// until the model produces a final text response or limits are reached.
func Run(ctx context.Context, req Request) (Result, error) {
	start := time.Now()
	const maxProviderAttempts = 5

	sessionID := fmt.Sprintf("s-%d", start.UnixNano())
	result := Result{
		SessionID:         sessionID,
		SelectedProvider:  req.SelectedProvider,
		SelectedRoute:     req.SelectedRoute,
		RequestedModel:    req.RequestedModel,
		RequestedModelRef: req.RequestedModelRef,
		ResolvedModelRef:  req.ResolvedModelRef,
		ResolvedModel:     req.ResolvedModel,
		Reasoning:         req.Reasoning,
	}

	if req.Provider == nil {
		return result, fmt.Errorf("agent: provider is required")
	}
	runtimeTelemetry := req.Telemetry
	if runtimeTelemetry == nil {
		runtimeTelemetry = telemetry.NewNoop()
	}
	defer runtimeTelemetry.Shutdown(context.Background())
	rootCtx, rootSpan := runtimeTelemetry.StartInvokeAgent(ctx, telemetry.InvokeAgentSpan{
		HarnessName:    telemetry.ServiceName,
		SessionID:      sessionID,
		ConversationID: sessionID,
		AgentName:      telemetry.ProductName,
	})
	ctx = rootCtx
	chatMetricsRecorder, _ := runtimeTelemetry.(telemetry.ChatMetricsRecorder)
	sessionCostObserved := false
	sessionCostKnown := true
	sessionCostSource := ""
	sessionCostCurrency := ""
	sessionCostPricingRef := ""
	sessionCostStable := true
	defer func() {
		applyRoutingReport(req.Provider, &result)
		applyRoutingSpanAttributes(rootSpan, result)
		applySessionCostAttributes(rootSpan, sessionCostObserved, sessionCostKnown, sessionCostSource, result.CostUSD, sessionCostCurrency, sessionCostPricingRef, sessionCostStable)
		if result.Error != nil {
			recordSpanError(rootSpan, result.Error)
		}
		rootSpan.End()
	}()

	// Build tool definitions for the provider
	toolDefs := make([]ToolDef, len(req.Tools))
	toolMap := make(map[string]Tool, len(req.Tools))
	for i, t := range req.Tools {
		toolDefs[i] = ToolDef{
			Name:        t.Name(),
			Description: t.Description(),
			Parameters:  t.Schema(),
		}
		toolMap[t.Name()] = t
	}

	// Build initial conversation
	messages := append([]Message(nil), req.History...)
	messages = append(messages, Message{Role: RoleUser, Content: req.Prompt})
	snapshotMessages := func() {
		result.Messages = append([]Message(nil), messages...)
	}

	// Emit session start
	sessionProvider, sessionModel := sessionStartIdentity(req.Provider)
	chatProviderSystem, chatServerAddress, chatServerPort := chatStartIdentity(req.Provider)
	emitCallback(req.Callback, Event{
		SessionID: sessionID,
		Seq:       0,
		Type:      EventSessionStart,
		Timestamp: time.Now().UTC(),
		Data: mustMarshal(map[string]any{
			"provider":            sessionProvider,
			"model":               sessionModel,
			"selected_provider":   req.SelectedProvider,
			"selected_route":      req.SelectedRoute,
			"requested_model":     req.RequestedModel,
			"requested_model_ref": req.RequestedModelRef,
			"resolved_model_ref":  req.ResolvedModelRef,
			"resolved_model":      req.ResolvedModel,
			"reasoning":           req.Reasoning,
			"work_dir":            req.WorkDir,
			"prompt":              req.Prompt,
			"system_prompt":       req.SystemPrompt,
			"max_iterations":      req.MaxIterations,
			"metadata":            req.Metadata,
		}),
	})

	seq := 1
	opts := Options{
		Temperature:       req.Temperature,
		TopP:              req.TopP,
		TopK:              req.TopK,
		MinP:              req.MinP,
		RepetitionPenalty: req.RepetitionPenalty,
		Seed:              req.Seed,
		SamplingSource:    req.SamplingSource,
		MaxTokens:         req.MaxTokens,
		Reasoning:         req.Reasoning,
		CachePolicy:       req.CachePolicy,
	}

	// Tool-call loop detection: abort when the same fingerprint repeats consecutively.
	const toolCallLoopLimit = 3
	var lastToolCallFingerprint string
	consecutiveToolCallCount := 0

	compactionCtx := ctx
	if req.SystemPrompt != "" {
		compactionCtx = compactionctx.WithPrefixTokens(compactionCtx, estimateCompactionPrefixTokens(req.SystemPrompt))
	}

	// Planning turn: one no-tool LLM call before the main loop. Failure is
	// non-fatal — the run continues without a plan.
	if req.PlanningMode {
		planMessages := make([]Message, 0, 2)
		if req.SystemPrompt != "" {
			planMessages = append(planMessages, Message{Role: RoleSystem, Content: req.SystemPrompt})
		}
		planMessages = append(planMessages, Message{Role: RoleUser, Content: planningPromptFor(req.Prompt)})

		emitCallback(req.Callback, Event{
			SessionID: sessionID,
			Seq:       seq,
			Type:      EventLLMRequest,
			Timestamp: time.Now().UTC(),
			Data: mustMarshal(map[string]any{
				"planning":           true,
				"messages":           planMessages,
				"tools":              nil,
				"model":              opts.Model,
				"temperature":        opts.Temperature,
				"top_p":              opts.TopP,
				"top_k":              opts.TopK,
				"min_p":              opts.MinP,
				"repetition_penalty": opts.RepetitionPenalty,
				"max_tokens":         opts.MaxTokens,
				"seed":               opts.Seed,
				"sampling_source":    opts.SamplingSource,
				"stop":               opts.Stop,
				"reasoning":          opts.Reasoning,
				"cache_policy":       opts.CachePolicy,
			}),
		})
		seq++

		planStart := time.Now()
		planResp, planErr := req.Provider.Chat(ctx, planMessages, nil, opts)
		planDuration := time.Since(planStart)

		if planErr != nil {
			slog.Warn("planning call failed, continuing without plan", "error", planErr)
		} else {
			result.Tokens.Add(planResp.Usage)
			emitCallback(req.Callback, Event{
				SessionID: sessionID,
				Seq:       seq,
				Type:      EventLLMResponse,
				Timestamp: time.Now().UTC(),
				Data: mustMarshal(map[string]any{
					"planning":      true,
					"content":       planResp.Content,
					"usage":         planResp.Usage,
					"latency_ms":    planDuration.Milliseconds(),
					"model":         planResp.Model,
					"finish_reason": planResp.FinishReason,
				}),
			})
			seq++
			emitCallback(req.Callback, Event{
				SessionID: sessionID,
				Seq:       seq,
				Type:      EventPlanningTurn,
				Timestamp: time.Now().UTC(),
				Data: mustMarshal(map[string]any{
					"plan":  planResp.Content,
					"usage": planResp.Usage,
					"model": planResp.Model,
				}),
			})
			seq++
			messages = append(messages, Message{
				Role:    RoleAssistant,
				Content: "<plan>\n" + planResp.Content + "\n</plan>",
			})
		}
	}

	// runCompaction handles the compaction logic and event emission.
	// midTurn should be true when called after tool results within a turn (as
	// opposed to pre-turn or overflow-triggered compaction), so event consumers
	// can distinguish the trigger source.
	// Returns true if compaction occurred; returns ErrCompactionNoFit when the
	// compactor could not produce an in-budget history.
	//
	// Event emission is suppressed for the pure no-op case (compactor decided
	// nothing to do). Start/End are emitted together only when compaction
	// actually ran or errored — otherwise every iteration would log a useless
	// pair of events.
	runCompaction := func(midTurn bool) (bool, *CompactionResult, error) {
		if req.Compactor == nil {
			return false, nil, nil
		}

		messagesBefore := len(messages)
		compacted, compResult, compErr := req.Compactor(compactionCtx, messages, req.Provider, result.ToolCalls)

		if compErr == nil && compResult == nil {
			return false, nil, nil
		}

		startData := map[string]any{"messages_before": messagesBefore}
		if midTurn {
			startData["mid_turn"] = true
		}
		emitCallback(req.Callback, Event{
			SessionID: sessionID,
			Seq:       seq,
			Type:      EventCompactionStart,
			Timestamp: time.Now().UTC(),
			Data:      mustMarshal(startData),
		})
		seq++

		var endData map[string]any
		if compErr != nil {
			endData = map[string]any{
				"error":           compErr.Error(),
				"success":         false,
				"no_compaction":   true,
				"messages_before": messagesBefore,
				"messages_after":  messagesBefore,

		return fmt.Sprintf("no viable routing candidate for pins %s: %d candidates rejected", strings.Join(pins, " "), e.Rejected)
	}
	return fmt.Sprintf("no viable routing candidate: %d candidates rejected", e.Rejected)
}

// ErrNoLiveProvider reports that profile-tier escalation walked the entire
// ladder (cheap → standard → smart) without finding a live provider that
// can serve the request. Callers translate this into a precise user-facing
// message naming the prompt size and tool requirement so operators know
// what capability is missing across all tiers.
type ErrNoLiveProvider struct {
	// PromptTokens is the request's EstimatedPromptTokens at the time
	// escalation began. Zero means no prompt-token gating was active.
	PromptTokens int
	// RequiresTools mirrors the request's RequiresTools flag.
	RequiresTools bool
	// StartingTier is the profile name that escalation began from
	// (the profile in the original request).
	StartingTier string
}

func (e *ErrNoLiveProvider) Error() string {
	return fmt.Sprintf("no live provider supports prompt of %d tokens with tools=%v at tier ≥ %s",
		e.PromptTokens, e.RequiresTools, e.StartingTier)
}

// ProfileEscalationLadder is the fixed cheap → standard → smart progression
// service.ResolveRoute walks when every candidate at the requested tier is
// filtered out (unhealthy or capability-rejected).
var ProfileEscalationLadder = []string{"cheap", "standard", "smart"}

// Inputs bundles the engine's external data sources.
type Inputs struct {
	Harnesses           []HarnessEntry
	HistoricalSuccess   map[string]float64   // by harness name; -1 = insufficient data
	ObservedSpeedTPS    map[string]float64   // by "provider:model"
	ProviderSuccessRate map[string]float64   // by ProviderModelKey(provider, endpoint, model)
	ObservedLatencyMS   map[string]float64   // by ProviderModelKey(provider, endpoint, model)
	ProviderCooldowns   map[string]time.Time // by provider name
	CooldownDuration    time.Duration        // 0 = no cooldown enforcement

	// ProviderQuotaExhaustedUntil maps provider name → retry_after time.
	// A provider with retry_after > Now is treated as quota_exhausted and
	// disqualified from candidate selection. The service maintains the
	// per-provider quota state machine and projects it into this map for
	// each routing call.
	ProviderQuotaExhaustedUntil map[string]time.Time
	Now                         time.Time // injected for deterministic testing; default time.Now()
	CatalogResolver             func(ref, surface string) (concreteModel string, ok bool)
	CatalogCandidatesResolver   func(ref, surface string) (concreteModels []string, ok bool)
	ModelEligibility            func(model string) (ModelEligibility, bool)

	// ReasoningResolver returns the catalog's surface_policy reasoning_default
	// for a (profile, surface) pair. When set, buildHarnessCandidates uses it
	// to resolve Reasoning=auto to a concrete level before invoking the
	// capability gate, so candidates that cannot satisfy the resolved level
	// (e.g. an off-only variant under a profile whose surface default is
	// "high") are correctly disqualified instead of slipping through.
	ReasoningResolver func(profile, surface string) (resolved string, ok bool)
}

